sparql:
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX dblp: <https://dblp.org/rdf/schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
SELECT (Count(*) as ?count) WHERE {
  ?paper rdf:type dblp:Publication .
}

PREFIX dblp: <https://dblp.org/rdf/schema#>
SELECT (MAX(?count_paper) as ?agg) WHERE { 
  { SELECT ?author (COUNT(DISTINCT ?paper) as ?count_paper) {
	?paper dblp:authoredBy ?author .
  }
  GROUP BY ?author
  }
}

PREFIX dblp: <https://dblp.org/rdf/schema#>
SELECT (MIN(?count_paper) as ?agg) WHERE { 
  { SELECT ?author (COUNT(DISTINCT ?paper) as ?count_paper) {
	?paper dblp:authoredBy ?author .
  }
  GROUP BY ?author
  }
}

PREFIX dblp: <https://dblp.org/rdf/schema#>
SELECT (AVG(?count_paper) as ?agg) WHERE { 
  { SELECT ?author (COUNT(DISTINCT ?paper) as ?count_paper) {
	?paper dblp:authoredBy ?author .
  }
  GROUP BY ?author
  }
}

PREFIX dblp: <https://dblp.org/rdf/schema#>
SELECT (SUM(?count_paper) as ?agg) WHERE { 
  { SELECT ?author (COUNT(DISTINCT ?paper) as ?count_paper) {
	?paper dblp:authoredBy ?author .
  }
  GROUP BY ?author
  }
}

PREFIX dblp: <https://dblp.org/rdf/schema#>
SELECT (COUNT(*) as ?count) WHERE {
  ?paper dblp:title ?title .
  FILTER CONTAINS (?title , "Database")
}

PREFIX dblp: <https://dblp.org/rdf/schema#>
SELECT ?year ?paper WHERE {
?paper dblp:yearOfPublication ?year .
}
ORDER BY ?year

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX dblp: <https://dblp.org/rdf/schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
SELECT * WHERE {
  ?paper rdf:type dblp:Publication .
}

PREFIX bibtex: <http://purl.org/net/nknouf/ns/bibtex#>
PREFIX dblp: <https://dblp.org/rdf/schema#>
SELECT ?paper WHERE {
  {
    ?paper dblp:bibtexType bibtex:Book .

  }
  UNION {
    ?paper dblp:bibtexType bibtex:Incollection .
  }
}

PREFIX bibtex: <http://purl.org/net/nknouf/ns/bibtex#>
PREFIX dblp: <https://dblp.org/rdf/schema#>
SELECT ?paper WHERE {
  {
    ?paper dblp:bibtexType bibtex:Article .

  }
  UNION {
    ?paper dblp:bibtexType bibtex:Inproceedings .

  }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX dblp: <https://dblp.org/rdf/schema#>
SELECT ?paper WHERE {
  {
    ?paper rdf:type dblp:Publication .
  }
  MINUS {
    ?paper dblp:yearOfPublication ?year .
    FILTER (?year >= "2000"^^xsd:gYear)
  }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX dblp: <https://dblp.org/rdf/schema#>
SELECT ?paper WHERE {
  {
    ?paper rdf:type dblp:Publication .
  }
  MINUS {
    ?paper dblp:yearOfPublication ?year .
    FILTER (?year <= "2000"^^xsd:gYear)
  }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX dblp: <https://dblp.org/rdf/schema#>
SELECT (COUNT(*) as ?count) WHERE {
  {
    ?paper rdf:type dblp:Publication .
  }
  Optional {
    ?paper dblp:publishedIn ?publishedin .
  }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX dblp: <https://dblp.org/rdf/schema#>
SELECT (Count(*) as ?count) WHERE {
  {
    ?author rdf:type dblp:Person .
  }
  Optional {
    ?author dblp:affiliation ?affiliation .
  }
}

PREFIX dblp: <https://dblp.org/rdf/schema#>
SELECT (SUM(STRLEN(?title)) AS ?length)  WHERE {
    ?paper dblp:title ?title .
}

PREFIX dblp: <https://dblp.org/rdf/schema#>
SELECT (SUM(STRLEN(STRBEFORE(?title, "a"))) AS ?length)  WHERE {
    ?paper dblp:title ?title .
}

PREFIX dblp: <https://dblp.org/rdf/schema#>
SELECT (SUM(STRLEN(STRAFTER(?title, "a"))) AS ?length)  WHERE {
    ?paper dblp:title ?title .
}

PREFIX dblp: <https://dblp.org/rdf/schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT (SUM(xsd:integer(STRSTARTS(?title, "a"))) AS ?count)  WHERE {
    ?paper dblp:title ?title .
}

PREFIX dblp: <https://dblp.org/rdf/schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT (SUM(xsd:integer(STRENDS(?title, "a"))) AS ?count)  WHERE {
    ?paper dblp:title ?title .
}
